function.arguments:
{"command":"python3 -c "
with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

sections = ['# Overview', '# Input data', '# Methods', '# Generated outputs', '# Main results', '# Limitations', '# Reproducibility']
for section in sections:
    start = content.find(section)
    if start == -1:
        print(f'MISSING: {section}')
    else:
        # Find next section or end of file
        next_start = content.find('\n# ', start + 1)
        if next_start == -1:
            text = content[start:]
        else:
            text = content[start:next_start]
        # Remove the header line
        lines = text.split('\n')
        if len(lines) > 1:
            text = '\n'.join(lines[1:])
        char_count = len(text)
        status = 'OK' if char_count >= 80 else 'TOO SHORT'
        print(f'{section}: {char_count} chars - {status}')""}
